def gen(rng):
    def fmt(a):
        return str(len(a) // 2) + '\n' + ' '.join(map(str, a))
    tests = [fmt([4, 6]), fmt([7, 7]), fmt([1, 1, 1, 1]), fmt([12, 18, 8, 6]), fmt([2, 3, 5, 7]),
             fmt([10**9, 10**9, 10**9, 10**9 - 1]), fmt([6, 4, 9, 3, 8, 12]), fmt([5, 10, 15, 20, 25, 30])]
    for n in (1, 2, 3, 4):
        for _ in range(3):
            tests.append(fmt([rng.randint(1, 30) for _ in range(2 * n)]))
    for _ in range(4):
        tests.append(fmt([rng.randint(1, 10**9) for _ in range(8)]))
    for n in (5, 6):
        tests.append(fmt([rng.randint(1, 60) for _ in range(2 * n)]))
    for _ in range(3):
        base = rng.randint(1, 10**3)
        tests.append(fmt([base * rng.randint(1, 10**6) for _ in range(10)]))
    N = 10
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(2 * N)]))
    tests.append(fmt([rng.choice([2, 3, 5, 7, 6, 10, 14, 15, 21, 30, 35, 42, 70, 105, 210]) * rng.randint(1, 4) * 1000 for _ in range(2 * N)]))
    tests.append(fmt([rng.randint(1, 120) for _ in range(2 * N)]))
    tests.append(fmt([2**rng.randint(0, 29) * 3**rng.randint(0, 5) for _ in range(2 * N)]))
    tests.append(fmt([10**9 - i for i in range(2 * N)]))
    tests.append(fmt([rng.randint(1, 10**9) // 720720 * 720720 or 720720 for _ in range(2 * N)]))
    tests.append(fmt([60060 * rng.randint(1, 10) if i % 2 else rng.randint(1, 10**9) for i in range(2 * N)]))
    return tests

